//! ECMAScript regexp operations over UTF-16, using the pinned pure-Rust regress
//! engine. RegExp identity, lastIndex writes and custom exec dispatch stay here.
use std::sync::Arc;
use crate::{Runtime,Value,StringId,JsError,JsResult,EnvId,ObjectKind};
use crate::closures::NativeFn;
const D:u16=1;const G:u16=2;const I:u16=4;const M:u16=8;const S:u16=16;const U:u16=32;const V:u16=64;const Y:u16=128;
pub(crate) struct RegexRecord{pub source:StringId,pub flags:u16,pub compiled:Arc<regress::Regex>}
fn arg(a:&[Value],i:usize)->Value{a.get(i).copied().unwrap_or(Value::Undefined)}
fn flags(units:&[u16])->JsResult<u16>{let mut result=0;for c in units{let flag=match *c{100=>D,103=>G,105=>I,109=>M,115=>S,117=>U,118=>V,121=>Y,_=>return Err(JsError::SyntaxError("Invalid flags supplied to RegExp constructor".into()))};if result&flag!=0{return Err(JsError::SyntaxError("Invalid flags supplied to RegExp constructor".into()))}result|=flag;}if result&U!=0&&result&V!=0{return Err(JsError::SyntaxError("Invalid flags supplied to RegExp constructor".into()))}Ok(result)}
fn flag_text(bits:u16)->String{[(D,'d'),(G,'g'),(I,'i'),(M,'m'),(S,'s'),(U,'u'),(V,'v'),(Y,'y')].into_iter().filter_map(|(flag,c)|(bits&flag!=0).then_some(c)).collect()}
fn codepoints(units:&[u16],unicode:bool)->Vec<u32>{let mut output=Vec::new();let mut i=0;while i<units.len(){let a=units[i];if unicode&&(0xd800..=0xdbff).contains(&a)&&i+1<units.len()&&(0xdc00..=0xdfff).contains(&units[i+1]){output.push(0x10000+((a as u32-0xd800)<<10)+(units[i+1]as u32-0xdc00));i+=2;}else{output.push(a as u32);i+=1;}}output}
fn escaped(units:&[u16])->Vec<u16>{if units.is_empty(){return "(?:)".encode_utf16().collect()}let mut output=Vec::new();let mut slash=false;for u in units{match *u{47 if !slash=>output.extend("\\/".encode_utf16()),10=>output.extend("\\n".encode_utf16()),13=>output.extend("\\r".encode_utf16()),0x2028=>output.extend("\\u2028".encode_utf16()),0x2029=>output.extend("\\u2029".encode_utf16()),_=>output.push(*u)}slash=if *u==92{!slash}else{false};}output}
fn advance(units:&[u16],index:usize,unicode:bool)->usize{if unicode&&index+1<units.len()&&(0xd800..=0xdbff).contains(&units[index])&&(0xdc00..=0xdfff).contains(&units[index+1]){index+2}else{index+1}}
impl Runtime{
 pub fn regexp(&mut self,pattern:&str,flags:&str)->JsResult<Value>{self.regexp_utf16(&pattern.encode_utf16().collect::<Vec<_>>(),flags)}
 pub fn regexp_utf16(&mut self,pattern:&[u16],flag_text:&str)->JsResult<Value>{let source=self.intern_utf16(pattern);let flags=flags(&flag_text.encode_utf16().collect::<Vec<_>>())?;self.new_regexp(source,flags)}
 fn regex_id(&self,value:Value)->JsResult<usize>{let id=self.object_id(value)?;if let ObjectKind::RegExp(id)=self.objects[id.0].kind{Ok(id)}else{Err(JsError::TypeError("RegExp method requires a RegExp receiver".into()))}}
 fn is_regexp(&self,value:Value)->bool{self.object_id(value).is_ok_and(|id|matches!(self.objects[id.0].kind,ObjectKind::RegExp(_)))}
 fn new_regexp(&mut self,source:StringId,flags:u16)->JsResult<Value>{let cache_key=(source,flags);let compiled=if let Some(compiled)=self.regex_cache.get(&cache_key){compiled.clone()}else{let unicode=flags&(U|V)!=0;let pattern=codepoints(self.string_units(source),unicode);let options=regress::Flags{icase:flags&I!=0,multiline:flags&M!=0,dot_all:flags&S!=0,unicode:flags&U!=0,unicode_sets:flags&V!=0,..Default::default()};let compiled=Arc::new(regress::Regex::from_unicode(pattern.into_iter(),options).map_err(|e|JsError::SyntaxError(e.to_string()))?);self.regex_cache.insert(cache_key,compiled.clone());compiled};let id=self.alloc_object(Some(self.regexp_prototype));let index=self.regex_records.len();self.regex_records.push(RegexRecord{source,flags,compiled});self.objects[id.0].kind=ObjectKind::RegExp(index);let key=self.string("lastIndex");self.define_data(Value::Object(id),key,Value::Number(0.0),true,false,false)?;Ok(Value::Object(id))}
 pub fn install_regexp_builtins(&mut self)->JsResult<()>{let prototype=Value::Object(self.regexp_prototype);let global=Value::Object(self.global_object);let constructor=self.builtin(global,"RegExp",2,regexp_constructor)?;self.set_function_constructible(constructor,true)?;self.regexp_constructor=constructor;let key=self.string("prototype");self.define_data(constructor,key,prototype,false,false,false)?;let key=self.string("constructor");self.define_data(prototype,key,constructor,true,false,true)?;for(name,arity,code)in[("exec",1,regexp_exec as NativeFn),("test",1,regexp_test as NativeFn),("toString",0,regexp_string as NativeFn)]{self.builtin(prototype,name,arity,code)?;}for(name,code)in[("source",source_get as NativeFn),("flags",flags_get as NativeFn),("global",global_get as NativeFn),("ignoreCase",icase_get as NativeFn),("multiline",multiline_get as NativeFn),("dotAll",dotall_get as NativeFn),("unicode",unicode_get as NativeFn),("unicodeSets",unicode_sets_get as NativeFn),("sticky",sticky_get as NativeFn),("hasIndices",indices_get as NativeFn)]{let function=self.native_function(&format!("get {name}"),0,code)?;let key=self.string(name);self.define_accessor(prototype,key,Some(function),None,false,true)?;}let string_proto=Value::Object(self.string_prototype);self.builtin(string_proto,"match",1,string_match)?;self.builtin(string_proto,"search",1,string_search)?;self.builtin(string_proto,"replace",2,string_replace)?;self.builtin(string_proto,"split",2,string_split)?;Ok(())}
 fn regex_builtin_exec(&mut self,regex:Value,input:StringId)->JsResult<Value>{let id=self.regex_id(regex)?;let flags=self.regex_records[id].flags;let key=self.string("lastIndex");let last=self.get(regex,key)?;let number=self.to_number(last)?;let start=if number.is_nan()||number<=0.0{0}else{number.floor().min(9_007_199_254_740_991.0)as usize};let start=if flags&(G|Y)==0{0}else{start};let units=self.string_units(input).to_vec();if start>units.len(){if flags&(G|Y)!=0{self.set(regex,key,Value::Number(0.0),true)?;}return Ok(Value::Null)}let compiled=self.regex_records[id].compiled.clone();let result=if flags&(U|V)!=0{compiled.find_from_utf16(&units,start).next()}else{compiled.find_from_ucs2(&units,start).next()};let Some(result)=result.filter(|m|flags&Y==0||m.range.start==start)else{if flags&(G|Y)!=0{self.set(regex,key,Value::Number(0.0),true)?;}return Ok(Value::Null)};if flags&(G|Y)!=0{self.set(regex,key,Value::Number(result.range.end as f64),true)?;}let mut values=Vec::new();for i in 0..=result.captures.len(){values.push(Some(if let Some(range)=result.group(i){self.string_utf16(&units[range])}else{Value::Undefined}));}let array=self.array(&values);for(name,value)in[("index",Value::Number(result.range.start as f64)),("input",Value::String(input))]{let k=self.string(name);self.define_data(array,k,value,true,true,true)?;}let names=result.named_groups().collect::<Vec<_>>();let groups=if names.is_empty(){Value::Undefined}else{let object=Value::Object(self.alloc_object(None));for(name,range)in &names{let value=range.clone().map(|r|self.string_utf16(&units[r])).unwrap_or(Value::Undefined);let key=self.string(name);self.define_data(object,key,value,true,true,true)?;}object};let key=self.string("groups");self.define_data(array,key,groups,true,true,true)?;if flags&D!=0{let mut ranges=Vec::new();for i in 0..=result.captures.len(){ranges.push(Some(if let Some(range)=result.group(i){self.array(&[Some(Value::Number(range.start as f64)),Some(Value::Number(range.end as f64))])}else{Value::Undefined}));}let indices=self.array(&ranges);let indices_groups=if names.is_empty(){Value::Undefined}else{let object=Value::Object(self.alloc_object(None));for(name,range)in names{let value=if let Some(range)=range{self.array(&[Some(Value::Number(range.start as f64)),Some(Value::Number(range.end as f64))])}else{Value::Undefined};let k=self.string(name);self.define_data(object,k,value,true,true,true)?;}object};let k=self.string("groups");self.define_data(indices,k,indices_groups,true,true,true)?;let k=self.string("indices");self.define_data(array,k,indices,true,true,true)?;}Ok(array)}
 fn regex_exec(&mut self,regex:Value,input:StringId)->JsResult<Value>{let key=self.string("exec");let method=self.get(regex,key)?;let result=if matches!(method,Value::Function(_)){self.call_value(method,regex,&[Value::String(input)])?}else{self.regex_builtin_exec(regex,input)?};if !matches!(result,Value::Null|Value::Object(_)|Value::Function(_)){return Err(JsError::TypeError("RegExp exec returned a non-object".into()))}Ok(result)}
}
fn regexp_constructor(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{let pattern=arg(args,0);let is_regex=rt.is_regexp(pattern);if is_regex&&!rt.is_construct_call()&&matches!(arg(args,1),Value::Undefined){let key=rt.string("constructor");if rt.get(pattern,key)?==rt.regexp_constructor{return Ok(pattern)}}let(source,bits)=if is_regex{let id=rt.regex_id(pattern)?;let source=rt.regex_records[id].source;let bits=if matches!(arg(args,1),Value::Undefined){rt.regex_records[id].flags}else{let flags_value=rt.to_string(arg(args,1))?;flags(rt.string_units(flags_value))?};(source,bits)}else{let source=if matches!(pattern,Value::Undefined){rt.intern("")}else{rt.to_string(pattern)?};let bits=if matches!(arg(args,1),Value::Undefined){0}else{let flags_value=rt.to_string(arg(args,1))?;flags(rt.string_units(flags_value))?};(source,bits)};let result=rt.new_regexp(source,bits)?;if rt.is_construct_call(){let a=rt.object_id(result)?;let b=rt.object_id(this)?;rt.objects[a.0].prototype=rt.objects[b.0].prototype;}Ok(result)}
fn regexp_exec(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{rt.regex_id(this)?;let input=rt.to_string(arg(args,0))?;rt.regex_builtin_exec(this,input)}
fn regexp_test(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{rt.object_id(this)?;let input=rt.to_string(arg(args,0))?;Ok(Value::Bool(!matches!(rt.regex_exec(this,input)?,Value::Null)))}
fn source_get(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{if rt.same_object(this,Value::Object(rt.regexp_prototype)){return Ok(rt.string("(?:)"))}let id=rt.regex_id(this)?;let units=escaped(rt.string_units(rt.regex_records[id].source));Ok(rt.string_utf16(&units))}
fn flag_get(rt:&mut Runtime,this:Value,bit:u16)->JsResult<Value>{if rt.same_object(this,Value::Object(rt.regexp_prototype)){return Ok(Value::Undefined)}let id=rt.regex_id(this)?;Ok(Value::Bool(rt.regex_records[id].flags&bit!=0))}
macro_rules! getter{($name:ident,$bit:ident)=>{fn $name(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{flag_get(rt,this,$bit)}}}
getter!(global_get,G);getter!(icase_get,I);getter!(multiline_get,M);getter!(dotall_get,S);getter!(unicode_get,U);getter!(unicode_sets_get,V);getter!(sticky_get,Y);getter!(indices_get,D);
fn flags_get(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{rt.object_id(this)?;let mut output=String::new();for(name,c)in[("hasIndices",'d'),("global",'g'),("ignoreCase",'i'),("multiline",'m'),("dotAll",'s'),("unicode",'u'),("unicodeSets",'v'),("sticky",'y')]{let key=rt.string(name);let value=rt.get(this,key)?;if rt.truthy(value){output.push(c)}}Ok(rt.string(&output))}
fn regexp_string(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{rt.object_id(this)?;let key=rt.string("source");let source=rt.get(this,key)?;let source=rt.to_string(source)?;let key=rt.string("flags");let flags=rt.get(this,key)?;let flags=rt.to_string(flags)?;let mut units=vec![47];units.extend_from_slice(rt.string_units(source));units.push(47);units.extend_from_slice(rt.string_units(flags));Ok(rt.string_utf16(&units))}
fn string_match(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{rt.require_object_coercible(this)?;let input=rt.to_string(this)?;let regex=if rt.is_regexp(arg(args,0)){arg(args,0)}else{regexp_constructor(rt,Value::Undefined,args,rt.global_env)?};let key=rt.string("global");let global=rt.get(regex,key)?;if !rt.truthy(global){return rt.regex_exec(regex,input)}let unicode_key=rt.string("unicode");let unicode_value=rt.get(regex,unicode_key)?;let unicode=rt.truthy(unicode_value);let last=rt.string("lastIndex");rt.set(regex,last,Value::Number(0.0),true)?;let mut values=Vec::new();loop{let result=rt.regex_exec(regex,input)?;if matches!(result,Value::Null){break}let zero=rt.string("0");let text=rt.get(result,zero)?;let text=rt.to_string(text)?;values.push(Some(Value::String(text)));if rt.string_units(text).is_empty(){let current=rt.get(regex,last)?;let current=rt.to_number(current)?.max(0.0).floor()as usize;let next=advance(rt.string_units(input),current,unicode);rt.set(regex,last,Value::Number(next as f64),true)?;}}if values.is_empty(){Ok(Value::Null)}else{Ok(rt.array(&values))}}
fn string_search(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{rt.require_object_coercible(this)?;let input=rt.to_string(this)?;let regex=if rt.is_regexp(arg(args,0)){arg(args,0)}else{regexp_constructor(rt,Value::Undefined,args,rt.global_env)?};let key=rt.string("lastIndex");let old=rt.get(regex,key)?;if !rt.same_value(old,Value::Number(0.0)){rt.set(regex,key,Value::Number(0.0),true)?;}let result=rt.regex_exec(regex,input)?;let current=rt.get(regex,key)?;if !rt.same_value(current,old){rt.set(regex,key,old,true)?;}if matches!(result,Value::Null){Ok(Value::Number(-1.0))}else{let key=rt.string("index");rt.get(result,key)}}
fn string_replace(_: &mut Runtime,_:Value,_:&[Value],_:EnvId)->JsResult<Value>{Err(JsError::Unsupported("String.replace is being installed with the RegExp backend".into()))}
fn string_split(_: &mut Runtime,_:Value,_:&[Value],_:EnvId)->JsResult<Value>{Err(JsError::Unsupported("String.split is being installed with the RegExp backend".into()))}
